// CloudWatch Synthetics canary (runtime syn-nodejs-5.x): a real user journey every run.
//   sign in (Cognito) -> submit a correct A + B solution -> wait for the AC verdict
// The canary user has no password anywhere: every run sets a fresh random password
// with the Cognito admin API (IAM) and signs in with ADMIN_USER_PASSWORD_AUTH.
// A thrown error fails the run; the failure alarm notifies the alerts topic.

const crypto = require("node:crypto");
const {
  CognitoIdentityProviderClient,
  AdminCreateUserCommand,
  AdminSetUserPasswordCommand,
  AdminInitiateAuthCommand,
  UsernameExistsException,
} = require("@aws-sdk/client-cognito-identity-provider");

const SITE_URL = process.env.SITE_URL;
const USER_POOL_ID = process.env.USER_POOL_ID;
const CLIENT_ID = process.env.CLIENT_ID;
const USERNAME = process.env.CANARY_USERNAME;
const VERDICT_TIMEOUT_MS = Number(process.env.VERDICT_TIMEOUT_MS || 240000);

const SOURCE = "a, b = map(int, input().split())\nprint(a + b)\n";

async function signIn() {
  const cognito = new CognitoIdentityProviderClient({});
  try {
    await cognito.send(
      new AdminCreateUserCommand({
        UserPoolId: USER_POOL_ID,
        Username: USERNAME,
        MessageAction: "SUPPRESS",
        UserAttributes: [
          { Name: "email", Value: USERNAME },
          { Name: "email_verified", Value: "true" },
        ],
      }),
    );
  } catch (err) {
    if (!(err instanceof UsernameExistsException)) throw err;
  }
  const password = `Cn${crypto.randomBytes(16).toString("hex")}Aa1`;
  await cognito.send(
    new AdminSetUserPasswordCommand({ UserPoolId: USER_POOL_ID, Username: USERNAME, Password: password, Permanent: true }),
  );
  const auth = await cognito.send(
    new AdminInitiateAuthCommand({
      UserPoolId: USER_POOL_ID,
      ClientId: CLIENT_ID,
      AuthFlow: "ADMIN_USER_PASSWORD_AUTH",
      AuthParameters: { USERNAME, PASSWORD: password },
    }),
  );
  return auth.AuthenticationResult.AccessToken;
}

async function api(path, token, init = {}) {
  const response = await fetch(`${SITE_URL}${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json", ...(init.headers || {}) },
  });
  const body = await response.text();
  return { status: response.status, body: body ? JSON.parse(body) : null };
}

exports.handler = async () => {
  const started = Date.now();
  const token = await signIn();

  const created = await api("/api/submissions", token, {
    method: "POST",
    headers: { "Idempotency-Key": crypto.randomUUID() },
    body: JSON.stringify({ problem: "a-plus-b", language: "python", source: SOURCE }),
  });
  if (created.status !== 202) throw new Error(`submit: HTTP ${created.status} ${JSON.stringify(created.body)}`);

  while (Date.now() - started < VERDICT_TIMEOUT_MS) {
    await new Promise((resolve) => setTimeout(resolve, 3000));
    const { status, body } = await api(`/api/submissions/${created.body.id}`, token);
    if (status !== 200) throw new Error(`poll: HTTP ${status}`);
    if (body.status === "done" || body.status === "failed") {
      if (body.verdict !== "AC") throw new Error(`verdict ${body.verdict}, want AC`);
      console.log(JSON.stringify({ event: "canary_ok", judge_ms: Date.now() - started }));
      return "AC";
    }
  }
  throw new Error(`no verdict within ${VERDICT_TIMEOUT_MS} ms`);
};
